input.command:
Get-Process codex*,node_repl* -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue; Start-Sleep -Seconds 2; $paths = @(
  'C:\Users\win\AppData\Local\Programs\OpenAI\Codex\bin\codex.exe',
  'C:\Users\win\.local\bin\codex.exe',
  (Get-ChildItem 'C:\Program Files\WindowsApps\OpenAI.Codex*\app\resources\codex.exe' -ErrorAction SilentlyContinue | Select-Object -First 1 -ExpandProperty FullName),
  (Get-ChildItem 'C:\Users\win\AppData\Local\OpenAI\Codex\bin\*\codex.exe' -ErrorAction SilentlyContinue | Select-Object -First 1 -ExpandProperty FullName)
); foreach ($p in $paths) { if ($p -and (Test-Path $p)) { Write-Host "=== $p ==="; & $p --version 2>&1; Write-Host "Exit: $LASTEXITCODE`n" } }

# 1) Stop stray processes
Get-Process codex*,node_repl* -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
Start-Sleep -Seconds 2

# 2) Remove conflicting third-party API key from USER env (codex-official uses OAuth)
$userKey = [Environment]::GetEnvironmentVariable('OPENAI_API_KEY','User')
if ($userKey) {
  [Environment]::SetEnvironmentVariable('OPENAI_API_KEY', $null, 'User')
  Write-Host "[OK] Removed User OPENAI_API_KEY (was third-party key conflicting with ChatGPT OAuth)"
}
Remove-Item Env:OPENAI_API_KEY -ErrorAction SilentlyContinue

# 3) Quarantine stale standalone CLI that wins PATH
$standalone = 'C:\Users\win\AppData\Local\Programs\OpenAI\Codex'
if (Test-Path $standalone) {
  $quarantine = "$standalone.disabled-$(Get-Date -Format 'yyyyMMdd')"
  if (-not (Test-Path $quarantine)) {
    Rename-Item $standalone $quarantine
    Write-Host "[OK] Quarantined stale standalone CLI -> $quarantine"
  }
}
$localBin = 'C:\Users\win\.local\bin\codex.exe'
if (Test-Path $localBin) {
  Rename-Item $localBin "$localBin.disabled" -Force
  Write-Host '[OK] Disabled ~/.local/bin/codex.exe shim'
}

# 4) Clear mixed runtime bins so desktop app re-downloads matching bundle
$binRoot = 'C:\Users\win\AppData\Local\OpenAI\Codex\bin'
if (Test-Path $binRoot) {
  Get-ChildItem $binRoot -Directory | Remove-Item -Recurse -Force
  Write-Host '[OK] Cleared stale Codex runtime bins (app will re-fetch on launch)'
}

Write-Host 'Done prep steps.'

$paths = @(
  "$env:LOCALAPPDATA\Microsoft\WinGet\Links\codex.exe",
  "$env:LOCALAPPDATA\Microsoft\WinGet\Packages\OpenAI.Codex*\codex.exe",
  "$env:ProgramFiles\Codex\codex.exe"
);
foreach ($p in $paths) { Get-ChildItem $p -ErrorAction SilentlyContinue | ForEach-Object { Write-Host $_.FullName; & $_.FullName --version 2>&1; Write-Host "Exit: $LASTEXITCODE`n" } }
Get-ChildItem "$env:LOCALAPPDATA\Microsoft\WinGet" -Recurse -Filter 'codex.exe' -ErrorAction SilentlyContinue | Select-Object -First 5 FullName,Length,LastWriteTime
